// features/lifecycle.feature: After a replacement, only the new document waits for review
import { expect, expectStatus, test } from "../../fixtures";
import type { Document } from "../../fixtures";

test("after a replacement, only the new document waits for review", { tag: "@LIF-05" }, async ({ factory, apiAs }) => {
  // Arrange: insurance and contract approved, w9 rejected (approvals first, since a rejection ends the review)
  const { vendor, extractions } = await factory.vendorInReview();
  const reviewer = await apiAs("reviewer");
  const member = await apiAs("member");
  for (const kind of ["insurance_certificate", "contract"] as const) {
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions[kind].id}/decision`, { data: { decision: "approve" } }),
      200,
    );
  }
  await expectStatus(
    await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
      data: { decision: "reject", note: "Please upload a signed W-9" },
    }),
    200,
  );

  // Act: upload a replacement w9, wait for extraction, resubmit
  const replacement = await factory.upload(vendor.id, "w9");
  await expect
    .poll(
      async () => (await expectStatus<Document>(await member.get(`/api/documents/${replacement.id}`), 200)).status,
      { message: "replacement w9 is extracted", timeout: 30_000 },
    )
    .toBe("extracted");
  const submitted = await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

  // Assert: vendor is in review, both in the response and as stored
  expect(submitted.status).toBe("in_review");
  const stored = await expectStatus(await member.get(`/api/vendors/${vendor.id}`), 200);
  expect(stored.status).toBe("in_review");

  // Assert: the queue lists the vendor with exactly one pending extraction, the new w9
  const queue = await expectStatus<
    { vendor_id: string; extractions: { kind: string; status: string; document_id: string }[] }[]
  >(await reviewer.get("/api/review-queue"), 200);
  const entries = queue.filter((item) => item.vendor_id === vendor.id);
  expect(entries, JSON.stringify(queue)).toHaveLength(1);
  expect(entries[0].extractions).toHaveLength(1);
  expect(entries[0].extractions[0].kind).toBe("w9");
  expect(entries[0].extractions[0].status).toBe("pending_review");
  expect(entries[0].extractions[0].document_id).toBe(replacement.id);
});
